FILES = {
    "seed_companion_context_v91.py": "\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\n\nSETTINGS_FILE = Path(\"seed_companion_context_v91_settings.json\")\nSTATE_FILE = Path(\"seed_companion_context_v91_state.json\")\nMEMORIES_FILE = Path(\"seed_memory_garden_v90_memories.jsonl\")\nNOTES_FILE = Path(\"seed_organism_notes_v89.jsonl\")\n\nDEFAULTS = {\n    \"version\": \"v91.0.0\",\n    \"memory_limit\": 12,\n    \"note_limit\": 6,\n    \"max_context_chars\": 3500,\n    \"include_note_only_rule\": True,\n    \"bootstrap_seed_milestone\": True\n}\n\nBASELINE_MEMORY_ID = \"mem_seed_v91_baseline_green\"\n\nBASELINE_MEMORY = {\n    \"memory_id\": BASELINE_MEMORY_ID,\n    \"source_note_id\": \"manual_v91_baseline\",\n    \"memory_type\": \"milestone\",\n    \"summary\": \"Seed baseline on Altan's Mac is green through v90.1.1: v88 Mac Body works, keyboard control works after Accessibility permission, v89 organism avatar/hearing/vision works in note-only mode, v89.2 filters low-value notes, and v90 Memory Garden archives junk with no promoted memories yet.\",\n    \"importance\": 96,\n    \"score\": 100,\n    \"tags\": [\"seed\", \"milestone\", \"mac_body\", \"organism\", \"memory_garden\", \"v91_baseline\"],\n    \"metadata\": {\"created_by\": \"seed_v91_context_bootstrap\"},\n    \"created_from_note_at\": None,\n    \"raw_audio_saved\": False,\n    \"raw_screenshot_saved\": False,\n    \"raw_transcript_saved\": False,\n    \"note_only_mode\": True\n}\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef load_settings():\n    if SETTINGS_FILE.exists():\n        try:\n            d = DEFAULTS.copy()\n            d.update(json.loads(SETTINGS_FILE.read_text(errors=\"ignore\")))\n            d[\"version\"] = \"v91.0.0\"\n            return d\n        except Exception:\n            pass\n    SETTINGS_FILE.write_text(json.dumps(DEFAULTS, indent=4, ensure_ascii=False))\n    return DEFAULTS.copy()\n\ndef read_jsonl(path, limit=5000):\n    path = Path(path)\n    if not path.exists():\n        return []\n    rows = []\n    for line in path.read_text(errors=\"ignore\").splitlines()[-limit:]:\n        try:\n            rows.append(json.loads(line))\n        except Exception:\n            pass\n    return rows\n\ndef append_jsonl(path, row):\n    row.setdefault(\"created_at\", now())\n    row.setdefault(\"version\", \"v91.0.0\")\n    with Path(path).open(\"a\") as f:\n        f.write(json.dumps(row, ensure_ascii=False) + \"\\n\")\n\ndef ensure_baseline_memory():\n    settings = load_settings()\n    if not settings.get(\"bootstrap_seed_milestone\", True):\n        return {\"ok\": True, \"created\": False, \"disabled\": True}\n\n    for row in read_jsonl(MEMORIES_FILE):\n        if row.get(\"memory_id\") == BASELINE_MEMORY_ID:\n            return {\"ok\": True, \"created\": False, \"memory_id\": BASELINE_MEMORY_ID}\n\n    append_jsonl(MEMORIES_FILE, BASELINE_MEMORY.copy())\n    return {\"ok\": True, \"created\": True, \"memory_id\": BASELINE_MEMORY_ID}\n\ndef promoted_memories(limit=None):\n    limit = int(limit or load_settings().get(\"memory_limit\", 12))\n    return read_jsonl(MEMORIES_FILE, limit)\n\ndef recent_notes(limit=None):\n    limit = int(limit or load_settings().get(\"note_limit\", 6))\n    rows = read_jsonl(NOTES_FILE, 5000)\n    useful = []\n    for row in rows:\n        if row.get(\"source\") == \"organism\":\n            continue\n        if row.get(\"raw_audio_saved\") or row.get(\"raw_screenshot_saved\") or row.get(\"raw_transcript_saved\"):\n            continue\n        summary = str(row.get(\"summary\", \"\")).strip()\n        if summary:\n            useful.append(row)\n    return useful[-limit:]\n\ndef status():\n    ensure = ensure_baseline_memory()\n    mems = promoted_memories()\n    notes = recent_notes()\n    data = {\n        \"created_at\": now(),\n        \"version\": \"v91.0.0\",\n        \"ok\": True,\n        \"baseline_memory\": ensure,\n        \"memory_count\": len(read_jsonl(MEMORIES_FILE, 5000)),\n        \"context_memories\": len(mems),\n        \"recent_notes\": len(notes),\n        \"settings\": load_settings()\n    }\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef build_context_text(max_chars=None):\n    ensure_baseline_memory()\n    settings = load_settings()\n    max_chars = int(max_chars or settings.get(\"max_context_chars\", 3500))\n\n    mems = promoted_memories(settings.get(\"memory_limit\", 12))\n    notes = recent_notes(settings.get(\"note_limit\", 6))\n\n    lines = []\n    lines.append(\"SEED COMPANION CONTEXT v91\")\n    lines.append(\"Identity: Seed is Altan's private local companion/friend, not a public product.\")\n    lines.append(\"Tone: natural, direct, helpful; Turkish if Altan uses Turkish; do not over-explain.\")\n    lines.append(\"Reality: Seed is not literally biologically alive; it can act organism-like through senses, memory, avatar, curiosity, and Mac body.\")\n    if settings.get(\"include_note_only_rule\", True):\n        lines.append(\"Privacy rule: raw audio, raw screenshots, and raw transcripts should not be saved. Store only important notes/memories.\")\n\n    if mems:\n        lines.append(\"\\nPROMOTED MEMORIES:\")\n        for m in mems[-int(settings.get(\"memory_limit\", 12)):]:\n            mt = m.get(\"memory_type\", \"memory\")\n            summary = str(m.get(\"summary\", \"\")).strip()\n            if summary:\n                lines.append(f\"- [{mt}] {summary}\")\n    else:\n        lines.append(\"\\nPROMOTED MEMORIES: none yet.\")\n\n    if notes:\n        lines.append(\"\\nRECENT NOTE-ONLY OBSERVATIONS:\")\n        for n in notes[-int(settings.get(\"note_limit\", 6)):]:\n            src = n.get(\"source\", \"note\")\n            summary = str(n.get(\"summary\", \"\")).strip()\n            if summary:\n                lines.append(f\"- [{src}] {summary}\")\n\n    text = \"\\n\".join(lines)\n    if len(text) > max_chars:\n        text = text[:max_chars-160] + \"\\n...[context trimmed]\"\n    return text\n\ndef show_status():\n    print(\"\\n=== SEED v91 COMPANION CONTEXT STATUS ===\")\n    print(json.dumps(status(), indent=4, ensure_ascii=False))\n\ndef show_context():\n    print(build_context_text())\n\nif __name__ == \"__main__\":\n    import sys\n    arg = sys.argv[1] if len(sys.argv) > 1 else \"status\"\n    if arg == \"status\":\n        show_status()\n    elif arg == \"context\":\n        show_context()\n    elif arg == \"bootstrap\":\n        print(ensure_baseline_memory())\n    else:\n        print(\"Commands: status | context | bootstrap\")\n",
    "seed_contextual_chat_v91.py": "\nimport json\nimport urllib.request\nfrom datetime import datetime\nfrom pathlib import Path\n\nSETTINGS_FILE = Path(\"seed_contextual_chat_v91_settings.json\")\nSTATE_FILE = Path(\"seed_contextual_chat_v91_state.json\")\n\nDEFAULTS = {\n    \"version\": \"v91.0.0\",\n    \"model\": \"gemma3:4b\",\n    \"fallback_model\": \"llama3.1:8b\",\n    \"ollama_url\": \"http://localhost:11434/api/generate\",\n    \"timeout\": 60,\n    \"num_predict\": 240,\n    \"temperature\": 0.35\n}\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef load_settings():\n    if SETTINGS_FILE.exists():\n        try:\n            d = DEFAULTS.copy()\n            d.update(json.loads(SETTINGS_FILE.read_text(errors=\"ignore\")))\n            d[\"version\"] = \"v91.0.0\"\n            return d\n        except Exception:\n            pass\n    SETTINGS_FILE.write_text(json.dumps(DEFAULTS, indent=4, ensure_ascii=False))\n    return DEFAULTS.copy()\n\ndef call_ollama(model, prompt):\n    s = load_settings()\n    payload = {\n        \"model\": model,\n        \"prompt\": prompt,\n        \"stream\": False,\n        \"keep_alive\": \"45m\",\n        \"options\": {\n            \"temperature\": float(s.get(\"temperature\", 0.35)),\n            \"num_predict\": int(s.get(\"num_predict\", 240))\n        }\n    }\n    req = urllib.request.Request(\n        s.get(\"ollama_url\"),\n        data=json.dumps(payload).encode(),\n        headers={\"Content-Type\": \"application/json\"},\n        method=\"POST\"\n    )\n    with urllib.request.urlopen(req, timeout=int(s.get(\"timeout\", 60))) as resp:\n        return json.loads(resp.read().decode()).get(\"response\", \"\").strip()\n\ndef build_prompt(user_message):\n    from seed_companion_context_v91 import build_context_text\n    context = build_context_text()\n    return f\"\"\"{context}\n\nTASK:\nReply as Seed to Altan's message.\n\nRules:\n- Be useful and direct.\n- Mention memory only when it helps.\n- Do not say you are literally alive or conscious.\n- Do not claim raw recordings/screenshots were saved.\n- If Altan asks for action on Mac, explain what Seed can do or suggest the exact command.\n- If Altan writes Turkish or slang Turkish, reply naturally in Turkish.\n\nAltan: {user_message}\nSeed:\"\"\"\n\ndef ask(user_message):\n    s = load_settings()\n    prompt = build_prompt(user_message)\n    models = [s.get(\"model\", \"gemma3:4b\"), s.get(\"fallback_model\", \"llama3.1:8b\")]\n    last_error = None\n    for model in models:\n        try:\n            reply = call_ollama(model, prompt)\n            data = {\"created_at\": now(), \"version\": \"v91.0.0\", \"ok\": True, \"model\": model, \"reply\": reply, \"route\": \"v91_contextual_chat\"}\n            STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n            return data\n        except Exception as e:\n            last_error = str(e)\n    data = {\"created_at\": now(), \"version\": \"v91.0.0\", \"ok\": False, \"error\": last_error}\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef warm():\n    s = load_settings()\n    return ask(\"Say only: ready\")\n\ndef status():\n    data = {\"created_at\": now(), \"version\": \"v91.0.0\", \"ok\": True, \"settings\": load_settings()}\n    if STATE_FILE.exists():\n        try:\n            data[\"last\"] = json.loads(STATE_FILE.read_text(errors=\"ignore\"))\n        except Exception:\n            pass\n    return data\n\nif __name__ == \"__main__\":\n    import sys\n    arg = sys.argv[1] if len(sys.argv) > 1 else \"status\"\n    if arg == \"ask\":\n        msg = \" \".join(sys.argv[2:]).strip() or \"hello\"\n        print(json.dumps(ask(msg), indent=4, ensure_ascii=False))\n    elif arg == \"warm\":\n        print(json.dumps(warm(), indent=4, ensure_ascii=False))\n    else:\n        print(json.dumps(status(), indent=4, ensure_ascii=False))\n",
    "seed_wake_context_v91.py": "\nimport json\nimport os\nimport signal\nimport subprocess\nimport sys\nimport time\nfrom datetime import datetime\nfrom pathlib import Path\n\nSETTINGS_FILE = Path(\"seed_wake_context_v91_settings.json\")\nPID_FILE = Path(\"seed_wake_context_v91.pid\")\nSTOP_FILE = Path(\"seed_wake_context_v91.stop\")\nLOG_FILE = Path(\"seed_wake_context_v91.log\")\nSTATUS_FILE = Path(\"seed_wake_context_v91_status.json\")\n\nDEFAULTS = {\n    \"version\": \"v91.0.0\",\n    \"wake_listen_seconds\": 2,\n    \"followup_seconds\": 7,\n    \"cooldown_seconds\": 3,\n    \"speak_reply\": True,\n    \"open_panel_on_wake\": True,\n    \"wake_phrases\": [\"wake up seed\", \"wake up\", \"hey seed\", \"ok seed\", \"okay seed\", \"seed\"],\n    \"wake_mishears\": [\"make up\", \"makeup\", \"weight up\", \"wait up\", \"wake app\"],\n    \"max_words_for_bare_seed\": 4\n}\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef load_settings():\n    if SETTINGS_FILE.exists():\n        try:\n            d = DEFAULTS.copy()\n            d.update(json.loads(SETTINGS_FILE.read_text(errors=\"ignore\")))\n            d[\"version\"] = \"v91.0.0\"\n            return d\n        except Exception:\n            pass\n    SETTINGS_FILE.write_text(json.dumps(DEFAULTS, indent=4, ensure_ascii=False))\n    return DEFAULTS.copy()\n\ndef write_status(**kw):\n    data = {\"created_at\": now(), \"version\": \"v91.0.0\"}\n    data.update(kw)\n    STATUS_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef norm(text):\n    import re\n    text = str(text or \"\").lower()\n    text = text.replace(\"wake upp\", \"wake up\")\n    text = re.sub(r\"[^a-z0-9\u00e7\u011f\u0131\u00f6\u015f\u00fc\\s]\", \" \", text)\n    return \" \".join(text.split())\n\ndef match_wake(text):\n    s = load_settings()\n    n = norm(text)\n    phrases = s.get(\"wake_phrases\", []) + s.get(\"wake_mishears\", [])\n    for phrase in sorted(phrases, key=len, reverse=True):\n        p = norm(phrase)\n        if not p:\n            continue\n        if n == p or n.startswith(p + \" \"):\n            inline = n[len(p):].strip()\n            if p == \"seed\" and inline == \"\" and len(n.split()) > int(s.get(\"max_words_for_bare_seed\", 4)):\n                continue\n            real_phrase = \"wake up\" if p in [norm(x) for x in s.get(\"wake_mishears\", [])] else phrase\n            return True, real_phrase, inline\n        if p in n and p != \"seed\":\n            before, after = n.split(p, 1)\n            if len(before.split()) <= 3:\n                real_phrase = \"wake up\" if p in [norm(x) for x in s.get(\"wake_mishears\", [])] else phrase\n                return True, real_phrase, after.strip()\n    return False, None, \"\"\n\ndef record_and_transcribe(seconds):\n    audio_path = None\n    try:\n        from seed_live_voice_v731 import record_audio, transcribe_audio\n        audio_path, device = record_audio(seconds)\n        transcript = transcribe_audio(audio_path)\n        text = (transcript.get(\"text\") or \"\").strip()\n        return {\"ok\": True, \"text\": text, \"device\": device}\n    except Exception as e:\n        return {\"ok\": False, \"text\": \"\", \"error\": str(e)}\n    finally:\n        try:\n            if audio_path:\n                Path(audio_path).unlink(missing_ok=True)\n        except Exception:\n            pass\n\ndef say(text):\n    if not load_settings().get(\"speak_reply\", True):\n        return False\n    try:\n        from seed_voice_v76 import say_with_settings\n        return say_with_settings(text)\n    except Exception:\n        try:\n            subprocess.run([\"say\", str(text)[:900]], timeout=70)\n            return True\n        except Exception:\n            return False\n\ndef open_panel():\n    if not load_settings().get(\"open_panel_on_wake\", True):\n        return False\n    try:\n        subprocess.Popen([\"open\", \"http://127.0.0.1:8797\"])\n        return True\n    except Exception:\n        return False\n\ndef ask_contextual(message):\n    from seed_contextual_chat_v91 import ask\n    return ask(message)\n\ndef listen_loop():\n    s = load_settings()\n    STOP_FILE.unlink(missing_ok=True)\n    print(\"\\n=== SEED v91 CONTEXTUAL WAKE LISTENER ===\")\n    print(\"Context: Memory Garden + organism state.\")\n    print(\"Wake: wake up / make up / hey seed / seed\")\n    print(\"Stop: Ctrl+C or python seed_wake_context_v91.py stop\")\n    write_status(ok=True, running=True, mode=\"listening\")\n    try:\n        while not STOP_FILE.exists():\n            res = record_and_transcribe(int(load_settings().get(\"wake_listen_seconds\", 2)))\n            if not res.get(\"ok\"):\n                print(\"[listen-error]\", res.get(\"error\"))\n                write_status(ok=False, mode=\"listen_error\", error=res.get(\"error\"))\n                time.sleep(1)\n                continue\n\n            text = res.get(\"text\", \"\")\n            print(\"[listen]\", text or \"[empty]\")\n            matched, phrase, inline = match_wake(text)\n            if not matched:\n                continue\n\n            print(f\"[{now()[11:19]}] WAKE phrase='{phrase}' transcript='{text}' inline='{inline}'\")\n            open_panel()\n\n            follow = inline\n            if not follow:\n                print(f\"[{now()[11:19]}] Listening for follow-up for {load_settings().get('followup_seconds', 7)}s...\")\n                res2 = record_and_transcribe(int(load_settings().get(\"followup_seconds\", 7)))\n                follow = (res2.get(\"text\") or \"\").strip()\n                print(f\"[{now()[11:19]}] Follow-up transcript: {follow or '[empty]'}\")\n\n            if follow:\n                print(f\"[{now()[11:19]}] Thinking with v91 context...\")\n                answer = ask_contextual(follow)\n                reply = answer.get(\"reply\", \"\")\n                print(f\"[{now()[11:19]}] Reply ready with {answer.get('model')}: {reply[:180]}\")\n                write_status(ok=True, mode=\"replied\", wake=text, followup=follow, reply=reply, model=answer.get(\"model\"))\n                if reply:\n                    say(reply)\n            else:\n                write_status(ok=True, mode=\"wake_no_followup\", wake=text)\n\n            time.sleep(float(load_settings().get(\"cooldown_seconds\", 3)))\n    except KeyboardInterrupt:\n        print(\"\\nSeed v91 wake listener stopped.\")\n        write_status(ok=True, running=False, mode=\"keyboard_interrupt\")\n    finally:\n        write_status(ok=True, running=False, mode=\"stopped\")\n\ndef pid_alive(pid):\n    try:\n        os.kill(int(pid), 0)\n        return True\n    except Exception:\n        return False\n\ndef start_daemon():\n    if PID_FILE.exists():\n        try:\n            pid = int(PID_FILE.read_text().strip())\n            if pid_alive(pid):\n                return {\"ok\": True, \"already_running\": True, \"pid\": pid}\n        except Exception:\n            pass\n    STOP_FILE.unlink(missing_ok=True)\n    log = LOG_FILE.open(\"a\")\n    proc = subprocess.Popen([sys.executable, \"seed_wake_context_v91.py\", \"listen\"], stdout=log, stderr=log)\n    PID_FILE.write_text(str(proc.pid))\n    return {\"ok\": True, \"pid\": proc.pid, \"log\": str(LOG_FILE)}\n\ndef stop_daemon():\n    STOP_FILE.write_text(now())\n    pid = None\n    stopped = False\n    if PID_FILE.exists():\n        try:\n            pid = int(PID_FILE.read_text().strip())\n            if pid_alive(pid):\n                os.kill(pid, signal.SIGTERM)\n                stopped = True\n            PID_FILE.unlink(missing_ok=True)\n        except Exception:\n            pass\n    return {\"ok\": True, \"pid\": pid, \"stopped\": stopped}\n\ndef wake_status():\n    pid = None\n    alive = False\n    if PID_FILE.exists():\n        try:\n            pid = int(PID_FILE.read_text().strip())\n            alive = pid_alive(pid)\n        except Exception:\n            pass\n    runtime = {}\n    if STATUS_FILE.exists():\n        try:\n            runtime = json.loads(STATUS_FILE.read_text(errors=\"ignore\"))\n        except Exception:\n            pass\n    return {\"created_at\": now(), \"version\": \"v91.0.0\", \"ok\": True, \"pid\": pid, \"alive\": alive, \"settings\": load_settings(), \"runtime\": runtime}\n\nif __name__ == \"__main__\":\n    arg = sys.argv[1] if len(sys.argv) > 1 else \"status\"\n    if arg == \"listen\":\n        listen_loop()\n    elif arg == \"start\":\n        print(start_daemon())\n    elif arg == \"stop\":\n        print(stop_daemon())\n    elif arg == \"ask\":\n        msg = \" \".join(sys.argv[2:]).strip() or \"hello\"\n        print(json.dumps(ask_contextual(msg), indent=4, ensure_ascii=False))\n    elif arg == \"test\":\n        msg = \" \".join(sys.argv[2:]).strip() or \"make up what are you\"\n        print({\"text\": msg, \"match\": match_wake(msg)})\n    elif arg == \"status\":\n        print(json.dumps(wake_status(), indent=4, ensure_ascii=False))\n    else:\n        print(\"Commands: listen | start | stop | ask <msg> | test <wake text> | status\")\n",
    "seed_natural_intent_router_v91.py": "\nimport re\n\ndef norm(text):\n    return \" \".join(str(text or \"\").strip().lower().split())\n\ndef handle_natural_intent_v91(user_message):\n    raw = str(user_message or \"\").strip()\n    text = norm(raw)\n    if not text or raw.startswith(\"/\"):\n        return None\n\n    if text in {\"v91 status\", \"context status\", \"companion context status\"}:\n        from seed_v91_systems import show_v91_status\n        show_v91_status()\n        return \"handled\"\n\n    if text in {\"seed context\", \"show context\", \"companion context\"}:\n        from seed_companion_context_v91 import show_context\n        show_context()\n        return \"handled\"\n\n    if text in {\"bootstrap context\", \"bootstrap memory\", \"seed baseline memory\"}:\n        from seed_companion_context_v91 import ensure_baseline_memory\n        print(ensure_baseline_memory())\n        return \"handled\"\n\n    if text in {\"start contextual wake\", \"start v91 wake\"}:\n        from seed_wake_context_v91 import start_daemon\n        print(start_daemon())\n        return \"handled\"\n\n    if text in {\"stop contextual wake\", \"stop v91 wake\"}:\n        from seed_wake_context_v91 import stop_daemon\n        print(stop_daemon())\n        return \"handled\"\n\n    m = re.match(r\"context ask\\s+(.+)$\", raw, flags=re.I)\n    if m:\n        from seed_contextual_chat_v91 import ask\n        print(ask(m.group(1).strip()).get(\"reply\", \"\"))\n        return \"handled\"\n\n    return None\n",
    "seed_v91_systems.py": "\nimport json\nfrom datetime import datetime\nfrom pathlib import Path\n\nSTATE_FILE = Path(\"seed_v91_systems_state.json\")\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef safe(title, summary, fn):\n    try:\n        data = fn()\n        return {\"title\": title, \"summary\": summary, \"status\": \"ok\" if data.get(\"ok\", True) else \"warning\", \"data\": data}\n    except Exception as e:\n        return {\"title\": title, \"summary\": summary, \"status\": \"error\", \"error\": str(e)}\n\ndef build_v91_state():\n    cards = [\n        safe(\"Companion Context\", \"Builds Seed identity + Memory Garden context for replies.\", lambda: __import__(\"seed_companion_context_v91\", fromlist=[\"status\"]).status()),\n        safe(\"Contextual Chat\", \"Direct Ollama chat that thinks with v91 context.\", lambda: __import__(\"seed_contextual_chat_v91\", fromlist=[\"status\"]).status()),\n        safe(\"Contextual Wake\", \"Wake listener that uses v91 contextual chat and wake mishear handling.\", lambda: __import__(\"seed_wake_context_v91\", fromlist=[\"wake_status\"]).wake_status()),\n    ]\n    data = {\"created_at\": now(), \"version\": \"v91.0.0\", \"ok\": all(c[\"status\"] != \"error\" for c in cards), \"cards\": cards}\n    STATE_FILE.write_text(json.dumps(data, indent=4, ensure_ascii=False))\n    return data\n\ndef show_v91_status():\n    data = build_v91_state()\n    print(\"\\n=== SEED v91 COMPANION CONTEXT STATUS ===\")\n    print(f\"OK: {data['ok']}\")\n    for c in data[\"cards\"]:\n        print(f\"- {c['title']}: {c['status']} \u2014 {c['summary']}\")\n\nif __name__ == \"__main__\":\n    show_v91_status()\n",
    "seed_v91_gate.py": "\nimport json, subprocess, sys\nfrom datetime import datetime\nfrom pathlib import Path\n\nMODULES = [\"seed_companion_context_v91.py\", \"seed_contextual_chat_v91.py\", \"seed_wake_context_v91.py\", \"seed_natural_intent_router_v91.py\", \"seed_v91_systems.py\", \"seed_v91_gate.py\"]\n\ndef now():\n    return datetime.now().isoformat(timespec=\"seconds\")\n\ndef comp(m):\n    p = subprocess.run([sys.executable, \"-m\", \"py_compile\", m], capture_output=True, text=True, timeout=30)\n    return {\"module\": m, \"ok\": p.returncode == 0, \"stderr\": p.stderr[-1000:]}\n\ndef run_v91_gate():\n    checks = [comp(m) for m in MODULES]\n    modules_ok = all(c[\"ok\"] for c in checks)\n    details = {}\n\n    try:\n        ctx = __import__(\"seed_companion_context_v91\", fromlist=[\"build_context_text\", \"status\", \"ensure_baseline_memory\"])\n        boot = ctx.ensure_baseline_memory()\n        text = ctx.build_context_text()\n        context_ok = (\"SEED COMPANION CONTEXT v91\" in text and \"private local companion\" in text and \"v90.1.1\" in text)\n        details[\"context_preview\"] = text[:500]\n        details[\"bootstrap\"] = boot\n    except Exception as e:\n        context_ok = False\n        details[\"context_error\"] = str(e)\n\n    try:\n        wake = __import__(\"seed_wake_context_v91\", fromlist=[\"match_wake\"])\n        wake_ok = (\n            wake.match_wake(\"make up what are you\")[0] is True and\n            wake.match_wake(\"weight up what are you\")[0] is True and\n            wake.match_wake(\"hello there\")[0] is False\n        )\n        details[\"wake_tests\"] = {\n            \"make_up\": wake.match_wake(\"make up what are you\"),\n            \"weight_up\": wake.match_wake(\"weight up what are you\"),\n            \"false\": wake.match_wake(\"hello there\")\n        }\n    except Exception as e:\n        wake_ok = False\n        details[\"wake_error\"] = str(e)\n\n    try:\n        systems = __import__(\"seed_v91_systems\", fromlist=[\"build_v91_state\"]).build_v91_state()\n        systems_ok = systems.get(\"ok\") is True and len(systems.get(\"cards\", [])) >= 3\n        details[\"systems\"] = {\"ok\": systems.get(\"ok\"), \"cards\": len(systems.get(\"cards\", []))}\n    except Exception as e:\n        systems_ok = False\n        details[\"systems_error\"] = str(e)\n\n    r = {\n        \"created_at\": now(),\n        \"version\": \"v91.0.0\",\n        \"ready\": modules_ok and context_ok and wake_ok and systems_ok,\n        \"modules_ok\": modules_ok,\n        \"context_ok\": context_ok,\n        \"wake_ok\": wake_ok,\n        \"systems_ok\": systems_ok,\n        \"module_checks\": checks,\n        \"details\": details\n    }\n    Path(\"seed_v91_gate_report.json\").write_text(json.dumps(r, indent=4, ensure_ascii=False))\n    return r\n\ndef show_v91_gate():\n    r = run_v91_gate()\n    print(\"\\n=== SEED v91 COMPANION CONTEXT GATE ===\")\n    print(f\"Ready: {r['ready']}\")\n    print(f\"Modules OK: {r['modules_ok']}\")\n    print(f\"Context OK: {r['context_ok']}\")\n    print(f\"Wake OK: {r['wake_ok']}\")\n    print(f\"Systems OK: {r['systems_ok']}\")\n    print(f\"Details: {r['details']}\")\n\nif __name__ == \"__main__\":\n    show_v91_gate()\n"
}

